// Lifted from AutomataFrameworkFailed@ed8592e8: tooling/api-report/src/report.ts (the writer only; reading a report
// back is for the break check, which waits until there is a published version to compare with).
// The committed API report: a heading per entry point, a heading and a `ts` block per export. It carries no version,
// so a release alone never makes it stale.
import type { PackageApi } from './extract.ts'

const NOTE =
  '<!-- Generated by `pnpm api-report --update` from source. Do not edit. A change here is a change to the public API. -->'

export function renderReport(api: PackageApi): string {
  const lines = [`# ${api.package} API report`, '', NOTE]
  for (const entry of api.entries) {
    lines.push('', `## \`${entry.entryPoint}\``)
    for (const exported of entry.exports) {
      lines.push('', `### \`${exported.name}\` (${exported.kind})`, '', '```ts', exported.declaration, '```')
    }
  }
  return `${lines.join('\n')}\n`
}
